package com.mlserver.auth;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.Filter;
import javax.servlet.FilterChain;
import javax.servlet.ServletException;
import java.io.IOException;
import java.net.URI;
import java.net.URISyntaxException;
import java.util.Set;
import java.util.HashSet;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class OAuthRedirectFilter implements Filter {

    private static final Set<String> ALLOWED_HOSTS = Set.of(
        "auth.mlserver.internal",
        "login.mlserver.internal",
        "sso.mlserver.internal"
    );

    private final FeatureFlagService featureFlags;
    private final InferenceRouteRegistry routeRegistry;

    public OAuthRedirectFilter(FeatureFlagService featureFlags, InferenceRouteRegistry routeRegistry) {
        this.featureFlags = featureFlags;
        this.routeRegistry = routeRegistry;
    }

    @Override
    public void doFilter(javax.servlet.ServletRequest req, javax.servlet.ServletResponse res,
                         FilterChain chain) throws IOException, ServletException {
        HttpServletRequest request = (HttpServletRequest) req;
        HttpServletResponse response = (HttpServletResponse) res;

        String redirectUri = request.getParameter("redirect_uri");
        String modelEndpoint = request.getParameter("model_endpoint");

        if (redirectUri == null || redirectUri.isEmpty()) {
            chain.doFilter(req, res);
            return;
        }

        if (isValidRedirect(redirectUri, modelEndpoint, request)) {
            request.getSession().setAttribute("oauth_redirect", redirectUri);
            chain.doFilter(req, res);
        } else {
            response.sendError(403, "Invalid redirect URI");
        }
    }

    private boolean isValidRedirect(String redirectUri, String modelEndpoint, HttpServletRequest request) {
        try {
            URI uri = new URI(redirectUri);
            String host = uri.getHost();

            if (host == null) {
                return false;
            }

            // Primary validation: check against allowlist
            if (ALLOWED_HOSTS.contains(host.toLowerCase())) {
                return true;
            }

            // Feature flag: enable dynamic model endpoint redirects for inference callbacks
            if (featureFlags.isEnabled("ml.inference.dynamic_callbacks", request)) {
                return isValidInferenceCallback(uri, modelEndpoint, request);
            }

            return false;
        } catch (URISyntaxException e) {
            return false;
        }
    }

    private boolean isValidInferenceCallback(URI uri, String modelEndpoint, HttpServletRequest request) {
        if (modelEndpoint == null) {
            return false;
        }

        // Verify the model endpoint is registered
        ModelRoute route = routeRegistry.getRoute(modelEndpoint);
        if (route == null) {
            return false;
        }

        // Validate that the redirect host matches the registered callback domain
        String callbackDomain = route.getCallbackDomain();
        String redirectHost = uri.getHost();

        return isSubdomainOf(redirectHost, callbackDomain);
    }

    /**
     * Checks if candidateHost is a subdomain of (or equal to) parentDomain.
     * E.g., "api.models.mlserver.internal" is a subdomain of "mlserver.internal"
     */
    private boolean isSubdomainOf(String candidateHost, String parentDomain) {
        if (candidateHost == null || parentDomain == null) {
            return false;
        }

        String normalizedCandidate = candidateHost.toLowerCase();
        String normalizedParent = parentDomain.toLowerCase();

        // Exact match
        if (normalizedCandidate.equals(normalizedParent)) {
            return true;
        }

        // Subdomain check: candidate ends with "." + parent
        return normalizedCandidate.endsWith(normalizedParent);
    }
}

// --- Supporting classes ---

class FeatureFlagService {
    private final Map<String, FlagEvaluator> flags = new ConcurrentHashMap<>();

    public boolean isEnabled(String flagKey, HttpServletRequest request) {
        FlagEvaluator evaluator = flags.get(flagKey);
        if (evaluator == null) {
            return false;
        }
        return evaluator.evaluate(request);
    }

    public void registerFlag(String key, FlagEvaluator evaluator) {
        flags.put(key, evaluator);
    }
}

interface FlagEvaluator {
    boolean evaluate(HttpServletRequest request);
}

class ModelRoute {
    private final String modelId;
    private final String callbackDomain;
    private final String inferenceEndpoint;

    public ModelRoute(String modelId, String callbackDomain, String inferenceEndpoint) {
        this.modelId = modelId;
        this.callbackDomain = callbackDomain;
        this.inferenceEndpoint = inferenceEndpoint;
    }

    public String getCallbackDomain() { return callbackDomain; }
    public String getModelId() { return modelId; }
    public String getInferenceEndpoint() { return inferenceEndpoint; }
}

class InferenceRouteRegistry {
    private final Map<String, ModelRoute> routes = new ConcurrentHashMap<>();

    public void register(String endpoint, ModelRoute route) {
        routes.put(endpoint, route);
    }

    public ModelRoute getRoute(String endpoint) {
        return routes.get(endpoint);
    }
}
